CrossmintEmbeddedOfframp.code:
import { View } from "react-native";
import {
    CrossmintEmbeddedOfframp,
    createCrossmintWalletSigner,
    useWallet,
    type EmbeddedOfframpCredentials,
    type OfframpStatus,
} from "@crossmint/client-sdk-react-native-ui";

export function WithdrawScreen({
    credentials,
    onClose,
    onStatus,
}: {
    credentials: EmbeddedOfframpCredentials;
    onClose: () => void;
    onStatus: (status: OfframpStatus, orderId?: string) => void;
}) {
    const { wallet } = useWallet();
    if (wallet == null) {
        return null;
    }

    return (
        <View style={{ flex: 1 }}>
            <CrossmintEmbeddedOfframp
                credentials={credentials}
                payer={createCrossmintWalletSigner(wallet)}
                fill
                onStatusChange={({ status, orderId }) => onStatus(status, orderId)}
                onComplete={({ orderId, txId }) => console.log("Withdrawal sent:", orderId, txId)}
                onCancel={onClose}
                onError={({ reason, retriable, message }) => {
                    console.error("Offramp error:", reason, message);
                    if (!retriable) {
                        onClose();
                    }
                }}
            />
        </View>
    );
}

